def ref_geom(H, W, kh, kw, sh, sw, pt, pb, pl, pr, ceil_mode):
    A = H + pt + pb - kh
    B = W + pl + pr - kw
    if not ceil_mode:
        oh = A // sh + 1
        ow = B // sw + 1
    else:
        oh = (A + sh - 1) // sh + 1
        ow = (B + sw - 1) // sw + 1
        if (oh - 1) * sh >= H + pt:
            oh -= 1
        if (ow - 1) * sw >= W + pl:
            ow -= 1
    return oh, ow


def ref_forward(x, kh, kw, sh, sw, pt, pb, pl, pr, include_pad, ceil_mode):
    N = len(x)
    C = len(x[0])
    H = len(x[0][0])
    W = len(x[0][0][0])
    oh, ow = ref_geom(H, W, kh, kw, sh, sw, pt, pb, pl, pr, ceil_mode)
    out = []
    counts = []
    for n in range(N):
        out_n, cnt_n = [], []
        for c in range(C):
            out_c, cnt_c = [], []
            for i in range(oh):
                bh = i * sh - pt
                row, crow = [], []
                for j in range(ow):
                    bw = j * sw - pl
                    total = 0.0
                    real = 0
                    decl = 0
                    for a in range(kh):
                        ih = bh + a
                        for b in range(kw):
                            iw = bw + b
                            in_real = 0 <= ih < H and 0 <= iw < W
                            in_decl = -pt <= ih < H + pb and -pl <= iw < W + pr
                            if in_real:
                                total += x[n][c][ih][iw]
                                real += 1
                            if in_decl:
                                decl += 1
                    count = decl if include_pad else real
                    row.append(total / count)
                    crow.append(count)
                out_c.append(row)
                cnt_c.append(crow)
            out_n.append(out_c)
            cnt_n.append(cnt_c)
        out.append(out_n)
        counts.append(cnt_n)
    return out, counts


