from convnet import AvgPool2D, check_gradients, check_cnn_gradients, Conv2D, Flatten, Linear


def ref_geom(H, W, kh, kw, sh, sw, pt, pb, pl, pr, ceil_mode):
    A = H + pt + pb - kh
    B = W + pl + pr - kw
    if not ceil_mode:
        oh = A // sh + 1
        ow = B // sw + 1
    else:
        oh = (A + sh - 1) // sh + 1
        ow = (B + sw - 1) // sw + 1
        if (oh - 1) * sh >= H + pt:
            oh -= 1
        if (ow - 1) * sw >= W + pl:
            ow -= 1
    return oh, ow


def ref_forward(x, kh, kw, sh, sw, pt, pb, pl, pr, include_pad, ceil_mode):
    N = len(x)
    C = len(x[0])
    H = len(x[0][0])
    W = len(x[0][0][0])
    oh, ow = ref_geom(H, W, kh, kw, sh, sw, pt, pb, pl, pr, ceil_mode)
    out = []
    counts = []
    for n in range(N):
        out_n, cnt_n = [], []
        for c in range(C):
            out_c, cnt_c = [], []
            for i in range(oh):
                bh = i * sh - pt
                row, crow = [], []
                for j in range(ow):
                    bw = j * sw - pl
                    total = 0.0
                    real = 0
                    decl = 0
                    for a in range(kh):
                        ih = bh + a
                        for b in range(kw):
                            iw = bw + b
                            in_real = 0 <= ih < H and 0 <= iw < W
                            in_decl = -pt <= ih < H + pb and -pl <= iw < W + pr
                            if in_real:
                                total += x[n][c][ih][iw]
                                real += 1
                            if in_decl:
                                decl += 1
                    count = decl if include_pad else real
                    row.append(total / count)
                    crow.append(count)
                out_c.append(row)
                cnt_c.append(crow)
            out_n.append(out_c)
            cnt_n.append(cnt_c)
        out.append(out_n)
        counts.append(cnt_n)
    return out, counts


def ref_backward(dy, counts, H, W, kh, kw, sh, sw, pt, pl):
    N = len(dy)
    C = len(dy[0])
    dx = [[[[0.0] * W for _ in range(H)] for _ in range(C)] for _ in range(N)]
    for n in range(N):
        for c in range(C):
            for i in range(len(dy[0][0])):
                bh = i * sh - pt
                for j in range(len(dy[0][0][0])):
                    bw = j * sw - pl
                    share = dy[n][c][i][j] / counts[n][c][i][j]
                    for a in range(kh):
                        ih = bh + a
                        if not (0 <= ih < H):
                            continue
                        for b in range(kw):
                            iw = bw + b
                            if 0 <= iw < W:
                                dx[n][c][ih][iw] += share
    return dx


def close(a, b):
    return abs(a - b) <= 1e-9 + 1e-9 * max(abs(a), abs(b))


def nested_eq(a, b):
    if isinstance(a, list):
        return len(a) == len(b) and all(nested_eq(x, y) for x, y in zip(a, b))
    return close(a, b)


def run_config(H, W, kh, kw, sh, sw, pad, include_pad, ceil_mode, seed):
    N, C = 1, 2
    x = [
        [
            [
                [
                    math.sin(seed + 3 * (n * C * H * W + c * H * W + h * W + w))
                    for w in range(W)
                ]
                for h in range(H)
            ]
            for c in range(C)
        ]
        for n in range(N)
    ]
    pt, pb, pl, pr = pad
    if kh > H + pt + pb or kw > W + pl + pr:
        try:
            layer = AvgPool2D((kh, kw), (sh, sw), pad,
                              count_include_pad=include_pad, ceil_mode=ceil_mode)
            layer.forward(x)
        except ValueError:
            return
        raise AssertionError("expected ValueError kernel>padded input")
    yref, counts = ref_forward(
        x, kh, kw, sh, sw, pt, pb, pl, pr, include_pad, ceil_mode
    )
    oh, ow = len(yref[0][0]), len(yref[0][0][0])
    dy = [
        [
            [
                [math.cos(1 + 7 * (n * C * oh * ow + c * oh * ow + i * ow + j))
                 for j in range(ow)]
                for i in range(oh)
            ]
            for c in range(C)
        ]
        for n in range(N)
    ]
    layer = AvgPool2D((kh, kw), (sh, sw), pad,
                      count_include_pad=include_pad, ceil_mode=ceil_mode)
    x_before = copy.deepcopy(x)
    dy_before = copy.deepcopy(dy)
    y = layer.forward(x)
    assert nested_eq(y, yref), "forward mismatch"
    dxref = ref_backward(dy, counts, H, W, kh, kw, sh, sw, pt, pl)
    dx = layer.backward(dy)
    assert nested_eq(dx, dxref), "backward mismatch"
    assert x == x_before and dy == dy_before, "args mutated"
