    bad_dy = [
        [
            [[0.0] * ow for _ in range(oh + 1)]
            for c in range(C)
        ]
        for n in range(N)
    ]
    try:
        layer.backward(bad_dy)
        raise AssertionError("expected ValueError for bad dy")
    except ValueError:
        pass
    # state intact
    assert layer._out_shape == (N, C, oh, ow)
    return oh, ow


